/* Deeper instruction and an editable application using the existing workbook store. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.REILessonDepth=api})(typeof window!=='undefined'?window:this,()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const lessons={
 question:{field:'question',entry:'working research question',title:'A question is a promise about evidence',concept:[
 'A topic names an area, such as learning apps. A research problem identifies a consequential difficulty or uncertainty and the evidence that makes it worth examining. A question turns that problem into something a study could answer. These are connected, but they are not interchangeable. “Students use an app” does not yet establish a problem, and “improve education” does not say what would be measured.',
 'Begin with the kind of understanding you need. Describing experiences requires relevant accounts; describing frequency requires a defined count and a defensible selection; studying a relationship requires measures of both constructs. Asking whether something caused improvement adds a much stronger design obligation. Narrowing the location alone does not resolve that obligation. A feasible question must also fit access, time, permissions and analysis.',
 'Use four boundaries: who or what, the phenomenon or variables, the setting, and the intended understanding. Then explain why the answer matters. A question can be narrow and still trivial; it can also be interesting but inaccessible. Revise the question until its significance and evidence needs can both be defended.'
 ],worked:[
 ['Start with the overclaim','“Does technology improve education in Leyte?” leaves technology, improvement, participants and evidence undefined. Interviews with a few students cannot estimate a province-wide causal effect.'],
 ['Identify an accessible decision','A fictional researcher can invite first-year IT students at one Isabel campus who use a particular study app. The aim is to understand how they plan their study, not to prove an effect on grades. Access and consent still need confirmation.'],
 ['Write the bounded question','“How do selected first-year IT students at one Isabel campus describe using the study app to plan their study?” The group, setting, practice and experience aim are visible. The question does not assume that the app helps.'],
 ['Test the promise','Relevant interviews could support an interpretation of these students’ accounts. The researcher must justify selection, interview prompts and analysis. Those accounts would not establish how common an experience is among all students or whether the app causes better grades.']
 ],mistake:['Narrowing only the place','“Does technology improve education in Isabel?” remains undefined and causal. Specify the technology, intended understanding and evidence; a smaller place is not a method.'],task:'Write one answerable research question. Under it, explain what evidence could answer it and one claim that evidence could not support.',checks:['The people or materials and setting are explicit.','The phenomenon or variables can be understood without guessing.','The aim matches evidence you can realistically access.','You name an important boundary instead of promising an unsupported effect.']},
 search:{field:'query',entry:'first search query',title:'Search a concept, not only your sentence',concept:[
 'A useful search balances coverage and relevance. Authors may discuss the same issue using different vocabulary. Searching only your proposed title can miss those studies, while a very broad word can return unrelated fields. Identify the concepts that must be present, then give each concept a small group of defensible alternatives.',
 'OR joins alternatives within a concept; AND asks for concepts to appear together. Parentheses keep those groups separate. Quotation marks usually request a phrase, but fields, phrase handling, wildcards and subject headings differ across databases. Check the help for the database you actually use. A query that works in one service is a starting strategy, not a universal command.',
 'Treat search as a documented revision process. Inspect relevant records for author vocabulary and controlled terms. If results are sparse, remove a restrictive concept or broaden a synonym; if results are noisy, add a meaningful concept or field. Record the database, date, exact query, filters, result count and changes. A failed search does not prove there are no studies or that your topic is novel.'
 ],worked:[
 ['Separate the concepts','For a fictional Leyte student-commuting topic, begin with travel and students. Study planning may be useful later; putting every detail into the first search may exclude relevant work.'],
 ['Build the groups','Travel: commuter OR commuting. Students: student OR undergraduate. Combine: (commuter OR commuting) AND (student OR undergraduate). These are candidate terms, not a validated final strategy.'],
 ['Inspect before restricting','Read promising titles and abstracts. Note whether researchers use travel time, transport access or another term. Check whether the database offers a relevant subject heading. Keep changes tied to relevance, not merely a larger number.'],
 ['Revise and keep a trail','If results are excessive, test a third group such as ("study planning" OR "time management"). If that hides useful records, return to the broader query and screen them. Log both attempts; use a Leyte-only limit only when it serves a justified purpose.']
 ],mistake:['Adding AND when results are already scarce','Every extra required concept can exclude records. First check spelling, syntax, overly narrow phrases and missing synonyms. Do not keep only sources that agree with your expectation.'],task:'Write a query with two concept groups. Below it, record the database, your next broadening or narrowing move, and why you would make that change.',checks:['Each OR group contains alternatives for the same concept.','AND connects distinct concepts with parentheses intact.','Syntax and filters have been checked for the actual database.','The strategy can be repeated, including date and revisions.']},
 read:{field:'evaluation',entry:'source evaluation',title:'Read for what a study can support',concept:[
 'Reading a paper is more than extracting a conclusion. Start with its question and identify the study design, participants or materials, selection, measures and analysis. These determine what the reported result means. The abstract helps you screen relevance; it usually cannot supply all the details needed to evaluate a strong claim.',
 'Keep three things separate: what was observed, how the authors interpret it, and your own interpretation. In a one-time survey, an association is an observed relationship, not evidence by itself that one variable caused another. For an interview study, a theme represents an interpretation of accounts under a stated analytic approach; it is not automatically a population frequency.',
 'A useful note preserves the source, page or section, relevant result, context and a specific limitation. Ask how that limitation changes the use of the finding. “Small sample” alone is less informative than explaining why a particular selection does not support a population estimate. If the detail you need is missing, record that uncertainty and seek it instead of supplying it yourself.'
 ],worked:[
 ['State what is actually reported','In a fictional volunteer survey at one Leyte campus, respondents with longer commutes also report less study time. This is the reported association; there is no reported random assignment or controlled comparison.'],
 ['Inspect the route from data to claim','Both travel and study time are self-reported at one time point. Volunteers may differ from other students. Paid work, schedules or other factors might relate to both measures. These are reasons to examine alternatives, not proof of a particular explanation.'],
 ['Write a usable evidence note','Record the paper identifier and actual page/section when working with a real source. Then write: “Among these respondents, longer reported commutes were associated with less reported study time.” Keep any exact quotation separate and marked.'],
 ['Explain the boundary','The result may inform a question about commuting and planning. It cannot establish that commuting caused reduced study time, describe every Leyte student, or show that a proposed transport intervention would work.']
 ],mistake:['Treating an attractive abstract as the full evidence','An abstract can justify checking a source. It cannot confirm omitted methods, sampling details or analytic decisions. Mark missing information and revisit the original before relying on it.'],task:'Evaluate one real source: name its design and selection, record a finding with a page/section, then explain one limitation and what it prevents you from claiming.',checks:['The finding is distinguishable from an interpretation.','The source and location can be found again.','Design, selection and measures are described rather than guessed.','The limitation changes a specific claim or use of the evidence.']},
 synthesis:{field:'pattern',entry:'provisional synthesis',title:'A synthesis explains relationships',concept:[
 'An article-by-article list tells a reader what you read. A synthesis explains what the studies collectively suggest about a question, where they differ and why that difference matters. Organize around an idea or theme, while keeping the original study boundaries visible.',
 'Compare like with like before calling findings contradictory. Two studies may use different definitions, populations, time periods, measures or methods. A survey of study hours and interviews about planning can illuminate related aspects without answering the same question. Agreement also needs scrutiny: similar findings from similar selection problems do not remove those problems.',
 'A research gap is a bounded uncertainty with a reason to investigate it. A new location alone does not establish a meaningful gap, and a small reading set cannot establish that nobody has studied an issue. Explain what your reviewed sources do and do not resolve, what further searching is needed, and why the remaining uncertainty matters to your proposed study.'
 ],worked:[
 ['Choose a comparison theme','Use “commuting and study planning” rather than separate headings for Paper A and Paper B. Both fictional sources concern student travel, but their evidence differs.'],
 ['Keep the difference visible','Study A is a volunteer survey associating reported travel duration with study hours. Study B uses interviews describing unpredictable delays and planning decisions. Neither source establishes a causal grade effect.'],
 ['Write the connection','“Across these fictional studies, travel duration and unpredictability appear relevant to students’ study arrangements. The survey describes a relationship in reported time, while interviews suggest how students account for adjusting plans.” This connects the contributions without merging unlike measures.'],
 ['Bound the uncertainty','“The sources reviewed do not resolve how selected students at the proposed campus adapt plans when travel is disrupted.” That is a provisional, context-bound uncertainty; further searching and evidence of local relevance are still needed.']
 ],mistake:['Declaring a gap after finding two papers','Two papers can help you practise comparison. They do not demonstrate comprehensive coverage, novelty or local need. Show your search boundaries and check alternative explanations for apparent disagreement.'],task:'Write a synthesis paragraph comparing two sources around one theme. Explain a difference in their evidence and end with a bounded uncertainty, not a claim that no research exists.',checks:['The paragraph is organized around an idea rather than author order.','Both sources make a visible contribution.','Methods or contexts help explain a meaningful difference.','The uncertainty is bounded to the sources reviewed and has a purpose.']},
 method:{field:'method',entry:'evidence collection and analysis',title:'Alignment is a chain of decisions',concept:[
 'A method label does not establish a suitable design. Begin with the research question and objective, then identify the evidence needed, how it can be obtained, and how the analysis will answer the objective. Selection, instruments, procedures, analysis and ethics must work together. Each additional objective creates another evidence obligation.',
 'Different aims create different requirements. Understanding accounts may call for qualitative evidence and an explicit interpretive approach. Describing a pattern needs defined measures and justified selection. An association needs measures of both constructs and consideration of other explanations. A causal effect requires a defensible comparison/design and attention to alternative causes; a one-time satisfaction survey cannot provide that simply because it uses numbers.',
 'Feasibility can legitimately change the question. If access, permissions or resources cannot support an effect study, a carefully justified descriptive or feasibility question may be more responsible. Explain that change openly. Do not retain a causal title and quietly collect data that answer a different question. Before recruitment, check the institution’s ethics process and the privacy/safety implications of the actual procedure.'
 ],worked:[
 ['Keep the objective specific','A fictional Education study asks how selected teachers at one Isabel school describe adapting reading activities. Its objective is to understand those adaptations, not to estimate a teaching intervention’s effect.'],
 ['Choose evidence that reaches the aim','Counts of submitted worksheets may describe activity but do not provide teachers’ accounts. Relevant interviews could address their explanations, if selection and prompts are justified and the required approvals and consent are obtained.'],
 ['Explain the analytic route','Specify how accounts will be recorded, transcribed or documented, examined and interpreted under the chosen qualitative approach. Show how excerpts, analytic decisions and themes will be traceable. Naming “thematic analysis” without describing the process is incomplete.'],
 ['Test the limit and practical access','Teacher accounts can inform an understanding of adaptation in the studied setting. They do not demonstrate improved learner scores. Avoid identifiable learner records unless appropriately authorized; confirm site access, time, recording choices and secure handling before proceeding.']
 ],mistake:['Measuring what is convenient instead of what is asked','A questionnaire about satisfaction does not measure learning improvement. Map each objective to a specific data source and analysis; revise an objective that your planned evidence cannot address.'],task:'Write one alignment row: question → objective → evidence → selection/collection → analysis → ethics and feasibility → claim limit.',checks:['Each objective has a corresponding evidence source.','The measure or account directly addresses the question.','The planned analysis explains how an answer will be produced.','Access, consent/privacy, feasibility and limits are concrete.']},
 claim:{field:'lesson',entry:'decision or lesson to transfer',title:'A claim needs a warrant and a boundary',concept:[
 'Evidence does not explain its own relevance. A research paragraph needs a claim, the source-linked evidence bearing on it, a reason the evidence supports that claim, and a boundary on what follows. This reasoning link is sometimes called a warrant. Adding a citation to a confident sentence does not repair a mismatch between the sentence and the study.',
 'Choose verbs that match the evidence. “Was associated with” does different work from “caused.” “Participants described” does different work from “all students believe.” A cautious paragraph is still useful when it states a clear contribution and explains its scope. Avoid making the sentence so vague that the reader cannot tell what the evidence adds.',
 'Carry the same question and objective across chapters. Chapter 1 establishes the problem, Chapter 2 explains the relevant evidence and uncertainty, Chapter 3 sets out a way to answer the question, and Chapter 4 reports actual results according to the required departmental structure. A proposal can plan that route; it must not invent results to make the argument look complete.'
 ],worked:[
 ['Identify the overreach','“Commuting causes poor academic performance among Leyte students” makes a causal, population-wide claim and introduces performance. The fictional source only reports a volunteer survey association between commute duration and study time.'],
 ['Match the reported evidence','“Among respondents in this fictional campus survey, longer reported commutes were associated with less reported study time.” The revised sentence names the evidence and scope without adding grades or causation.'],
 ['Add the reasoning link','“The pattern makes study scheduling worth examining alongside travel conditions.” This explains the relevance to a planning question without asserting that changing transport will improve grades.'],
 ['State the boundary and next need','“Self-report, volunteer selection and unmeasured differences limit interpretation; accounts of how students adapt their plans could help investigate that process.” A real paragraph also needs the actual source citation and verification of what it reports.']
 ],mistake:['Replacing one exaggerated verb and leaving the rest','Changing “proves” to “suggests” is insufficient if the sentence still generalizes to an unsupported population or names an unmeasured outcome. Check verb, population, measure and comparison together.'],task:'Draft a paragraph with a bounded claim, a source-linked result, your reasoning link and one consequential limitation. Identify the actual source; do not cite the fictional teaching example.',checks:['The source supports the named result and outcome.','The verb matches the design and evidence type.','Your reasoning explains why the result matters.','The population, setting and limitation are visible.']},
 ethics:{field:'ethics',entry:'ethics, feasibility and claim limits',title:'Apply ethics before the work is collected',concept:[
 'Ethical practice begins before recruitment and continues through analysis and writing. Plan who may access the material, what participants understand, what identifying details are necessary, how long records will be kept, and how quotations or recordings could expose someone. A signed form cannot compensate for pressure to participate or promises your data-handling plan cannot keep.',
 'Citation, permission and authorship are related but distinct. A citation acknowledges a source; it does not automatically grant permission to reproduce an image, instrument or long passage. Disclosing AI use does not make a prohibited use acceptable. Check the required rules for your actual work and keep a record of the decisions you made.'
 ],worked:[
 ['Before inviting participants','A fictional Isabel interview project seeks voluntary student accounts. Confirm the required institutional review and permissions first. Explain participation and refusal in understandable language without implying an effect on grades or services.'],
 ['Separate choices','Consent to an interview is not automatically consent to audio recording or to publishing an identifiable quotation. State the choices and explain privacy and withdrawal limits honestly.'],
 ['Keep interpretation accountable','Store exact quotations separately from paraphrases and interpretations. Check every real citation in the original. Do not manufacture evidence or put confidential participant information into an AI tool without appropriate authorization.'],
 ['Before sharing','Audit attribution, participant exposure and any permitted AI contribution. Ask the adviser about an unresolved policy question before submitting, and make required disclosures specific to what actually happened.']
 ],mistake:['Treating disclosure as a permission slip','A label such as “AI-assisted” does not override a course rule or authorize uploading private data. Check permission first, then document the allowed task and how you verified it.'],task:'Write your study’s actual ethics plan: recruitment/consent, recording choices, privacy/access, retention/deletion, source attribution and any permitted AI use. Mark unresolved requirements to confirm with your adviser.',checks:['Institutional review and access requirements are identified before recruitment.','Consent is voluntary and understandable, with recording and withdrawal explained.','Privacy, access and retention plans match the actual material collected.','Attribution and any AI disclosure describe what actually happened.']}
 };
 function concept(id){const d=lessons[id];return d?`<section class="lesson-depth" id="lesson-understand"><h2 tabindex="-1">${esc(d.title)}</h2>${d.concept.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`:''}
 function worked(id){const d=lessons[id];return d?`<ol class="depth-reasoning">${d.worked.map(([title,text],i)=>`<li><span aria-hidden="true">${i+1}</span><div><h3>${esc(title)}</h3><p>${esc(text)}</p></div></li>`).join('')}</ol><section class="depth-pitfall"><h3>Common mistake: ${esc(d.mistake[0])}</h3><p>${esc(d.mistake[1])}</p></section>`:''}
 function application(id,value){const d=lessons[id];if(!d)return '';if(value===undefined){try{value=window.REILearningStore.readPath().fields[d.field]||''}catch{value=''}}return `<section class="lesson-depth depth-application" id="lesson-apply"><h2 tabindex="-1">Apply it to your own study</h2><p>${esc(d.task)}</p><label for="depth-draft">Your ${esc(d.entry)}<textarea id="depth-draft" data-depth-field="${d.field}" rows="8" maxlength="3000">${esc(value)}</textarea></label><p class="depth-save" data-depth-save role="status">This edits the same ${esc(d.entry)} entry in My work. Existing text is shown above. Keep a downloaded backup.</p><button type="button" class="path-link" data-depth-retry>Save this writing</button><details class="depth-self-review"><summary>Check the reasoning in your draft</summary><p>Use these to revise; REI does not grade your explanation.</p><ul>${d.checks.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></details><a class="path-link" href="#workbook">See this in My work ↗</a></section>`}
 function persist(editor,store){const d=Object.values(lessons).find(x=>x.field===editor.dataset.depthField);if(!d)throw Error('Unknown workbook field');const path=store.readPath();path.fields[d.field]=editor.value.slice(0,3000);return store.writePath(path)}
 if(typeof document!=='undefined'){
  const save=editor=>{const status=document.querySelector('[data-depth-save]');try{const ok=persist(editor,window.REILearningStore);if(status)status.textContent=ok?'Saved in My work on this device. Included in your workbook backup.':'Not saved to browser storage. Your writing remains in this session; keep this page open, retry or download a backup.';}catch{if(status)status.textContent='Writing could not be saved. Keep this page open and download a backup before leaving.'}};
  document.addEventListener('input',e=>{if(e.target.matches('[data-depth-field]'))save(e.target)});
  document.addEventListener('click',e=>{if(e.target.closest('[data-depth-retry]')){const editor=document.querySelector('[data-depth-field]');if(editor)save(editor)}});
 }
 const topicSpecs=id=>id==='ethics'?[
  ['lesson-citation','Cite sources','Learn how paraphrases and quotations credit a source.','Cite the idea; mark the exact words'],
  ['lesson-plagiarism','Avoid plagiarism','Distinguish your contribution from borrowed wording and ideas.','Plagiarism is more than copying a paragraph'],
  ['lesson-consent','Plan consent','Check voluntary participation, privacy and recording choices.','Consent comes before participation'],
  ['lesson-ai','Use AI honestly','Check permission, verification and disclosure before using a tool.','Use AI with permission and a record'],
  ['lesson-understand','Follow the case','Trace the ethical decisions before, during and after collection.'],
  ['lesson-decision','Check a decision','Choose a response and inspect the explanation.','Check your decision'],
  ['lesson-apply','Write your plan','Apply these safeguards to your actual study and save your thinking.']
 ]:[
  ['lesson-understand','Understand','Start with the explanation. Identify the rule and the boundary it protects.'],
  ['lesson-example','Follow the example','Read each reasoning step and notice why the weaker approach changes.'],
  ['lesson-decision','Make a decision','Choose an answer, read its feedback and explain the better-fitting choice.'],
  ['lesson-transfer','Try a new situation','Use the same rule in a different context before checking the feedback.'],
  ['lesson-apply','Apply to my study','Write your own response, then use the self-review to revise it.']
 ];
 function guide(id,hasDraft=false){const first=topicSpecs(id)[0][0];return `<section class="lesson-start-guide" aria-labelledby="lesson-start-title"><h2 id="lesson-start-title">${hasDraft?'Pick up your thinking.':'A simple way through this lesson.'}</h2><p>${hasDraft?'You have writing in this lesson’s workbook entry. Continue it, or revisit the explanation before you revise.':'First time here? Begin with the explanation. You do not need a finished topic or a perfect answer.'}</p><ol><li><strong>Understand</strong><span>Read the idea and follow the example.</span></li><li><strong>Practise</strong><span>Make a decision and inspect the feedback.</span></li><li><strong>Apply</strong><span>Write for your own study and review it.</span></li></ol><div class="lesson-start-actions"><button type="button" data-library-jump="${hasDraft?'lesson-apply':first}">${hasDraft?'Continue my writing':'Start with the explanation'}</button><button type="button" data-library-jump="${hasDraft?first:'lesson-apply'}">${hasDraft?'Revisit the explanation':'I’m ready to write'}</button></div><p class="lesson-start-note">Work at your own pace. A saved response is not a grade; choose the next lesson when you are ready.</p></section>`}
 let navigationObserver=null;
 function unmount(){navigationObserver?.disconnect();navigationObserver=null}
 function mount(id){
  unmount();if(!lessons[id]||typeof document==='undefined')return;
  const article=document.querySelector(id==='ethics'?'.seminar-reading':'.library-lesson');if(!article||article.dataset.depthNavigation)return;article.dataset.depthNavigation=id;
  const specs=topicSpecs(id),topics=[];
  for(const [target,label,hint,headingText] of specs){let section=document.getElementById(target);if(!section&&headingText){section=[...article.querySelectorAll('section')].find(s=>s.querySelector(':scope>h2')?.textContent===headingText);if(section)section.id=target}const heading=section?.querySelector('h2');if(!heading)continue;const number=topics.length+1;heading.classList.add('lesson-topic-heading');heading.tabIndex=-1;heading.insertAdjacentHTML('afterbegin',`<span class="lesson-topic-number" aria-hidden="true">${String(number).padStart(2,'0')}</span>`);section.classList.add('lesson-topic');section.dataset.lessonTopic=target;heading.insertAdjacentHTML('afterend',`<p class="lesson-topic-purpose">${esc(hint)}</p>`);const oldNumber=section.querySelector('.lesson-section-heading>span');if(oldNumber)oldNumber.remove();topics.push({target,label,section,number});}
  if(!topics.length)return;
  let hasDraft=false;try{hasDraft=!!window.REILearningStore.readPath().fields[lessons[id].field]?.trim()}catch{}
  const header=article.querySelector(':scope>header');if(header)header.insertAdjacentHTML('afterend',guide(id,hasDraft));else article.insertAdjacentHTML('afterbegin',guide(id,hasDraft));
  const compass=document.querySelector('.lesson-compass nav');if(compass){compass.setAttribute('aria-label','Topics in this lesson');compass.innerHTML=topics.map(t=>`<button type="button" data-library-jump="${t.target}"><span class="lesson-nav-number" aria-hidden="true">${t.number}</span><span>${esc(t.label)}</span></button>`).join('');}
  article.insertAdjacentHTML('beforebegin',`<nav class="lesson-topic-picker" aria-label="Jump between lesson topics"><label for="lesson-topic-select">In this lesson</label><select id="lesson-topic-select" data-depth-section-select>${topics.map(t=>`<option value="${t.target}">${t.number}. ${esc(t.label)}</option>`).join('')}</select></nav>`);
  const select=document.querySelector('[data-depth-section-select]');
  const activate=target=>{select.value=target;document.querySelectorAll('.lesson-compass [data-library-jump]').forEach(b=>{if(b.dataset.libraryJump===target)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')})};
  select.addEventListener('change',()=>{const target=document.getElementById(select.value);target?.scrollIntoView({behavior:'auto',block:'start'});target?.querySelector('h2')?.focus({preventScroll:true});activate(select.value)});
  activate(topics[0].target);
  if(typeof IntersectionObserver!=='undefined'){navigationObserver=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>Math.abs(a.boundingClientRect.top-120)-Math.abs(b.boundingClientRect.top-120));if(visible[0])activate(visible[0].target.dataset.lessonTopic)},{rootMargin:'-100px 0px -55% 0px',threshold:0});topics.forEach(t=>navigationObserver.observe(t.section));}
 }
 if(typeof addEventListener==='function')addEventListener('rrh:route',unmount);
 return {lessons,concept,worked,application,persist,topicSpecs,guide,mount,unmount};
});
